    { name: "Marteau de l'aurore", rarity: "Rare", category: "Offensif", effect: "Une fois par tour, le jet de dégâts radiants du porteur est doublé s'il vise un fiélon, un mort-vivant ou une aberration." },
    { name: "Poing de force pure", rarity: "Rare", category: "Offensif", effect: "Une fois par tour, tant que le porteur a moins de la moitié de ses PV, son jet de dégâts de force est doublé." },
    { name: "Couronne de l'esprit brisé", rarity: "Rare", category: "Magique", effect: "Une fois par tour, le jet de dégâts psychiques du porteur est doublé s'il vise une créature Charmée, Effrayée ou Neutralisée." },
    { name: "Gantelets d'adamant", rarity: "Rare", category: "Offensif", effect: "Les attaques d'arme du porteur ignorent complètement les résistances et les immunités aux dégâts contondants, perforants et tranchants." },
    { name: "Rune de percée élémentaire", rarity: "Rare", category: "Magique", effect: "Les dégâts de feu, de froid, de foudre et de tonnerre infligés par le porteur ignorent les résistances (pas les immunités)." },
    { name: "Rune de percée occulte", rarity: "Rare", category: "Magique", effect: "Les dégâts nécrotiques, radiants, de force et psychiques infligés par le porteur ignorent les résistances (pas les immunités)." },
    { name: "Fiole d'acide pur", rarity: "Rare", category: "Offensif", effect: "Les dégâts d'acide et de poison infligés par le porteur ignorent les résistances, et une immunité au poison est traitée comme une simple résistance." },
    { name: "Écusson du chevalier", rarity: "Rare", category: "Ressources", effect: "Le porteur gagne Second souffle : deux fois par étage, action Bonus pour récupérer 1d10 + son niveau en PV." },
    { name: "Cape du roublard", rarity: "Rare", category: "Utilitaire", effect: "Le porteur peut utiliser son action Bonus pour effectuer l'action Se précipiter, Se désengager ou Se cacher (Ruse)." },
    { name: "Sandales du vent", rarity: "Rare", category: "Utilitaire", effect: "Le porteur peut utiliser son action Bonus pour se précipiter ou se désengager, et ses sauts sont doublés en distance (Pas du vent)." },
    { name: "Gri-gri du barbare", rarity: "Rare", category: "Défensif", effect: "Avantage aux jets d'initiative et aux jets de sauvegarde de Dextérité contre les effets que le porteur peut voir (Sens du danger)." },
    { name: "Chapelet du paladin", rarity: "Rare", category: "Ressources", effect: "Le porteur dispose d'une réserve de soins égale à 5 × son niveau, reconstituée à chaque étage. Par une action, il touche une créature et lui rend autant de PV qu'il le souhaite (Imposition des mains)." },
    { name: "Pendentif du clerc", rarity: "Rare", category: "Magique", effect: "Une fois par combat, le porteur peut utiliser une action : les morts-vivants et fiélons à 30 ft doivent réussir un jet de sauvegarde de Sagesse ou être Effrayés pendant 1 minute (DD 8 + bonus de maîtrise + modificateur d'incantation)." },
    { name: "Cor du rôdeur", rarity: "Rare", category: "Offensif", effect: "Une fois par combat, le porteur désigne une créature comme son ennemi juré : avantage aux tests de Perception et de Survie à son sujet et +1 × son bonus de maîtrise aux dégâts contre elle." },
    { name: "Sceau de métamagie", rarity: "Rare", category: "Magique", effect: "Une fois par étage chacun, le porteur peut accélérer un sort de niveau 3 ou moins (action Bonus) et jumeler un sort de niveau 3 ou moins (une seconde cible)." },
    { name: "Bague de l'occultiste", rarity: "Rare", category: "Magique", effect: "Le porteur connaît Décharge occulte (1d10 force) et ajoute son modificateur d'incantation aux dégâts de chaque rayon." },
    { name: "Grimoire du magicien", rarity: "Rare", category: "Défensif", effect: "Quand le porteur lance un sort avec un emplacement, il gagne des PV temporaires égaux à 3 × le niveau de l'emplacement dépensé (Barrière arcanique)." },
    { name: "Archet du barde", rarity: "Rare", category: "Utilitaire", effect: "Le porteur ajoute la moitié de son bonus de maîtrise (arrondi inférieur) aux tests de caractéristique sans maîtrise, et double son bonus de maîtrise pour deux compétences maîtrisées (Polyvalence, Expertise)." },
    { name: "Totem de l'ours", rarity: "Rare", category: "Défensif", effect: "Une fois par combat, le porteur peut utiliser une action Bonus : pendant 1 minute, il résiste aux dégâts contondants, perforants et tranchants." },
    { name: "Gantelets du fendeur", rarity: "Rare", category: "Offensif", effect: "Une fois par tour, quand le porteur réduit une créature à 0 PV avec une attaque de mêlée, il peut effectuer une attaque supplémentaire contre une autre créature à portée." },
    { name: "Arc de la forêt dorée", rarity: "Rare", category: "Offensif", effect: "Si le porteur ne s'est pas déplacé pendant son tour, il peut effectuer une attaque à distance supplémentaire en action Bonus. (Le Seigneur des Anneaux)" },
    { name: "Lames sœurs", rarity: "Rare", category: "Offensif", effect: "Quand le porteur touche la même créature avec deux attaques d'arme dans un même tour, il peut effectuer une troisième attaque contre elle." },
    { name: "Brassard de représailles", rarity: "Rare", category: "Offensif", effect: "Quand une créature touche le porteur avec une attaque de mêlée, il peut utiliser sa réaction pour effectuer une attaque d'arme contre elle, avec avantage." },
    { name: "Sabre laser", rarity: "Rare", category: "Hybride", effect: "Les attaques d'arme du porteur infligent 1d8 dégâts de force supplémentaires. En réaction, il peut dévier une attaque à distance : dégâts réduits de 1d10 + son niveau ; à 0, il renvoie l'attaque sur une créature à 60 ft. (Star Wars)" },
    { name: "Bouclier Holtzman", rarity: "Rare", category: "Défensif", effect: "Les attaques à distance et les sorts d'attaque qui ciblent le porteur ont le désavantage. En contrepartie, le porteur a le désavantage à ses propres attaques à distance. (Dune)" },
    { name: "Bouclier hylien", rarity: "Rare", category: "Défensif", effect: "Une fois par round, le porteur peut utiliser sa réaction pour gagner +5 CA contre une attaque à distance ou un sort d'attaque ; si elle manque, elle est renvoyée vers son auteur. (The Legend of Zelda)" },
    { name: "Anneau de Havel", rarity: "Rare", category: "Défensif", effect: "Tant que le porteur porte une armure lourde, il résiste aux dégâts contondants, perforants et tranchants non magiques et sa vitesse n'est pas réduite par l'armure. (Dark Souls)" },
    { name: "Cape d'invisibilité", rarity: "Rare", category: "Utilitaire", effect: "Une fois par étage, le porteur peut utiliser une action pour devenir Invisible pendant 1 minute ou jusqu'à ce qu'il attaque ou lance un sort. (Harry Potter)" },
    { name: "Cotte de mithril", rarity: "Rare", category: "Défensif", effect: "+1 CA avec une armure, aucun désavantage en Discrétion. Une fois par étage, un coup critique contre le porteur est traité comme une touche normale. (Le Seigneur des Anneaux)" },
    { name: "Palantír", rarity: "Rare", category: "Utilitaire", effect: "Au début de chaque étage, le porteur connaît le type (facile, moyen, difficile ou boss) du prochain combat. (Le Seigneur des Anneaux)" },
    { name: "Toison d'or", rarity: "Rare", category: "Ressources", effect: "Une fois par étage, le porteur peut utiliser une action pour rendre 3d8 + son niveau en PV à lui-même et aux alliés à 30 ft. (Percy Jackson)" },
    { name: "Queue de phénix", rarity: "Rare", category: "Ressources", effect: "Une fois par étage, le porteur peut utiliser une action Bonus pour relever un allié à 0 PV situé à 30 ft ou moins avec 2d8 + son niveau PV. (Final Fantasy)" },
    { name: "Anaklusmos", rarity: "Rare", category: "Hybride", effect: "Les attaques d'arme du porteur infligent 1d6 dégâts radiants supplémentaires aux morts-vivants et aux fiélons. Si l'arme est perdue ou lâchée, elle revient en main par une action Bonus. (Percy Jackson)" },
    { name: "Lame d'alerte", rarity: "Rare", category: "Utilitaire", effect: "Le porteur ne peut pas être surpris et gagne +4 aux jets d'initiative. Une fois par combat, il a l'avantage à ses jets d'attaque jusqu'à la fin de son premier tour. (Le Seigneur des Anneaux)" },
    { name: "Shikai", rarity: "Rare", category: "Transformation", effect: "Une fois par étage, le porteur peut utiliser une action Bonus : jusqu'à la fin du combat, son arme inflige 1d8 dégâts supplémentaires d'un type choisi (feu, froid, foudre ou nécrotique). (Bleach)" },
    { name: "Côtes de Susanoo", rarity: "Rare", category: "Défensif", effect: "Au début de chaque combat, le porteur gagne des PV temporaires égaux à 3 × son niveau. (Naruto)" },
    { name: "Fruit du caoutchouc", rarity: "Rare", category: "Défensif", effect: "Consommable. En mangeant ce fruit, le porteur résiste aux dégâts de foudre et aux dégâts contondants ; sa portée de mêlée augmente de 5 ft. L'effet est permanent. Drawback : le porteur ne sait pas nager (vitesse de nage 0 s'il en avait une). (One Piece)" },
    { name: "Fruit de la flamme", rarity: "Rare", category: "Magique", effect: "Consommable. En mangeant ce fruit, le porteur résiste aux dégâts de feu. Une fois par combat, par une action, les créatures à 15 ft de lui subissent 3d6 dégâts de feu (Dextérité pour moitié). L'effet est permanent. Drawback : le porteur ne sait pas nager. (One Piece)" },
    { name: "Haki de l'armement", rarity: "Rare", category: "Offensif", effect: "Les attaques d'arme du porteur sont considérées comme magiques, peuvent toucher les créatures intangibles et infligent 1d4 dégâts de force supplémentaires. (One Piece)" },
    { name: "Haki de l'observation", rarity: "Rare", category: "Défensif", effect: "Une fois par round, quand une créature cible le porteur avec une attaque, il peut utiliser sa réaction pour lui imposer le désavantage. (One Piece)" },
    { name: "Étincelle noire", rarity: "Rare", category: "Offensif", effect: "Une fois par étage, une attaque du porteur qui touche est un coup critique et inflige 2d10 dégâts de force supplémentaires. (Jujutsu Kaisen)" },
    { name: "Poing spectral", rarity: "Rare", category: "Hybride", effect: "Les frappes à mains nues du porteur ont une allonge de 10 ft et infligent 1d6 dégâts de force supplémentaires. (JoJo's Bizarre Adventure)" },
    { name: "Sharingan", rarity: "Rare", category: "Défensif", effect: "Une fois par combat, quand une créature touche le porteur, il peut utiliser sa réaction pour forcer l'attaquant à relancer l'attaque avec le désavantage. (Naruto)" },
    { name: "Poing Jajanken", rarity: "Rare", category: "Offensif", effect: "Une fois par étage, le porteur peut se concentrer pendant une action : sa prochaine attaque de mêlée avant la fin de son prochain tour inflige 5d10 dégâts de force supplémentaires. (Hunter x Hunter)" },
    { name: "Épée Buster", rarity: "Rare", category: "Offensif", effect: "Quand le porteur subit en une fois des dégâts égaux à au moins 25 % de ses PV maximum, sa prochaine attaque d'arme inflige 2d10 dégâts supplémentaires. (Final Fantasy)" },
    { name: "Rebellion", rarity: "Rare", category: "Offensif", effect: "Chaque attaque qui touche la même créature dans un même tour inflige 1d4 dégâts supplémentaires de plus que la précédente (1d4, 2d4, 3d4…). (Devil May Cry)" },
    { name: "Pistolets jumeaux", rarity: "Rare", category: "Offensif", effect: "Le porteur peut attaquer avec deux armes à distance Légères comme avec deux armes de mêlée Légères et n'a pas de désavantage à attaquer à distance au corps à corps. (Devil May Cry)" },
    { name: "Cœur d'âme", rarity: "Rare", category: "Défensif", effect: "Au début de chaque étage, le porteur gagne des PV temporaires égaux à 3 × son niveau, qui persistent jusqu'à épuisement. (The Binding of Isaac)" },
    { name: "Bandolier", rarity: "Rare", category: "Offensif", effect: "Chaque créature que le porteur réduit à 0 PV charge l'artefact (maximum 5). Sa prochaine attaque qui touche consomme les charges et inflige 1d4 dégâts supplémentaires par charge. (Risk of Rain)" },
    { name: "Bénédiction d'Arès", rarity: "Rare", category: "Offensif", effect: "Une fois par combat, quand le porteur touche une créature, celle-ci est condamnée : à la fin de son prochain tour, elle subit 3d10 dégâts nécrotiques. (Hades)" },
    { name: "Bénédiction d'Athéna", rarity: "Rare", category: "Défensif", effect: "Une fois par round, le porteur peut utiliser sa réaction pour réduire de 1d10 + son bonus de maîtrise les dégâts d'une attaque qui le touche. (Hades)" },
    { name: "Bénédiction d'Apollon", rarity: "Rare", category: "Offensif", effect: "Une fois par combat, quand le porteur touche une créature, celle-ci subit 1d6 dégâts radiants supplémentaires et est Aveuglée jusqu'à la fin de son prochain tour. (Hades)" },
    { name: "Bottes de Pégase", rarity: "Rare", category: "Utilitaire", effect: "+30 ft de vitesse, le terrain difficile ne ralentit pas le porteur et ses déplacements ne provoquent pas d'attaques d'opportunité. (The Legend of Zelda)" },
    { name: "Épée de légende", rarity: "Rare", category: "Hybride", effect: "Les attaques d'arme du porteur infligent 1d8 dégâts radiants supplémentaires aux fiélons et aux morts-vivants. Une fois par étage, il lance un faisceau d'épée : attaque à distance à 60 ft, 4d8 dégâts radiants. (The Legend of Zelda)" },
    { name: "Cape de lévitation", rarity: "Rare", category: "Utilitaire", effect: "Une fois par combat, le porteur peut voler pendant 1 minute avec une vitesse de vol égale à sa vitesse de marche. (Doctor Strange)" },
    { name: "Anneau de transfert", rarity: "Rare", category: "Utilitaire", effect: "Une fois par combat, le porteur peut utiliser une action Bonus pour se téléporter jusqu'à 40 ft dans un espace inoccupé visible. (Doctor Strange)" },
    { name: "Lames enchaînées", rarity: "Rare", category: "Offensif", effect: "La portée de mêlée du porteur augmente de 10 ft. Une fois par tour, quand il touche, il peut attirer la cible à 5 ft de lui (Force, DD 8 + bonus de maîtrise + modificateur de Force, sinon attirée). (God of War)" },
    { name: "Épée vorpale", rarity: "Rare", category: "Offensif", effect: "+3 aux jets d'attaque et de dégâts. Sur un 20 naturel contre une créature avec une tête, elle est décapitée (immunisées : les créatures sans tête, les boss). (Objet DnD)" },
    { name: "Hache du berserker", rarity: "Rare", category: "Hybride", effect: "+2 aux jets d'attaque et de dégâts. Quand le porteur tue une créature, il peut continuer à frapper en action Bonus jusqu'à ce qu'il manque ou qu'il n'y ait plus de cible à 5 ft. Drawback : au début de chaque combat, le porteur doit réussir un jet de Sagesse DD 15 ou être contraint d'attaquer la créature la plus proche (alliés inclus) à son premier tour. (Objet DnD)" },
    { name: "Armure d'écailles de dragon", rarity: "Rare", category: "Défensif", effect: "+1 CA. Le porteur résiste à un type de dégâts selon la couleur des écailles (feu, froid, foudre, acide ou poison, défini à l'équipement). (Objet DnD)" },
    { name: "Fléau de disruption", rarity: "Rare", category: "Offensif", effect: "+2 aux jets d'attaque et de dégâts. Sur un 20 naturel contre un mort-vivant ou un fiélon, la cible doit réussir un jet de Constitution DD 17 ou être détruite. (Objet DnD)" },

    // --- ÉPIQUES ---
    { name: "Gantelet de fougue", rarity: "Épique", category: "Transformation", effect: "Deux fois par étage, le porteur peut effectuer une action supplémentaire lors de son tour de combat. (Action Surge)" },
    { name: "Totem du berserker", rarity: "Épique", category: "Transformation", effect: "Deux fois par étage, le porteur peut entrer en Rage par une action Bonus pendant 1 minute : avantage aux tests et sauvegardes de Force, +2 aux dégâts de mêlée (+3 au niveau 9, +4 au niveau 16), résistance aux dégâts contondants, perforants et tranchants. Impossible de lancer des sorts." },
    { name: "Cape du chasseur nocturne", rarity: "Épique", category: "Offensif", effect: "Au premier round de chaque combat, le porteur gagne +10 ft de vitesse et une attaque supplémentaire avec l'action Attaquer, qui inflige 2d6 dégâts psychiques supplémentaires si elle touche (Dread Ambusher)." },
    { name: "Totem de la bête", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, le porteur peut prendre la forme d'une bête de FP au plus égal à son niveau divisé par 3 (maximum 6) pendant 10 minutes. Il retrouve ses PV d'origine à la fin de la transformation (Forme sauvage)." },
    { name: "Voile du maître roublard", rarity: "Épique", category: "Offensif", effect: "Le porteur peut infliger sa Frappe sournoise deux fois par tour, sur deux attaques différentes." },
    { name: "Poing de l'éveillé", rarity: "Épique", category: "Offensif", effect: "Une fois par combat, quand le porteur touche une créature avec une frappe à mains nues, celle-ci doit réussir un jet de sauvegarde de Constitution (DD 8 + bonus de maîtrise + modificateur de Sagesse) ou être Étourdie jusqu'à la fin du prochain tour du porteur." },
    { name: "Aura du chevalier", rarity: "Épique", category: "Défensif", effect: "Le porteur et les alliés à 10 ft ou moins ajoutent son bonus de maîtrise à leurs jets de sauvegarde et sont immunisés contre l'état Effrayé tant que le porteur est conscient." },
    { name: "Étoile du paladin", rarity: "Épique", category: "Offensif", effect: "Trois fois par étage, quand le porteur touche avec une attaque d'arme, il inflige 2d8 dégâts radiants supplémentaires sans dépenser d'emplacement de sort (Châtiment divin)." },
    { name: "Orbe de signature", rarity: "Épique", category: "Magique", effect: "Le porteur choisit deux sorts de niveau 3 qu'il connaît : il peut lancer chacun une fois par étage sans dépenser d'emplacement de sort." },
    { name: "Cœur de l'ensorceleur", rarity: "Épique", category: "Ressources", effect: "Le porteur gagne 6 points de sorcellerie supplémentaires et, une fois par étage, en récupère 4." },
    { name: "Sceau du pacte supérieur", rarity: "Épique", category: "Ressources", effect: "Après chaque combat, le porteur récupère tous ses emplacements de pacte dépensés." },
    { name: "Livre des chants héroïques", rarity: "Épique", category: "Magique", effect: "Au début de chaque combat, le porteur récupère toutes ses utilisations d'Inspiration bardique, et ses alliés à 30 ft ont l'avantage aux jets de sauvegarde contre les états Effrayé et Charmé." },
    { name: "Sceptre du clerc", rarity: "Épique", category: "Magique", effect: "Une fois par étage, le porteur peut lancer un sort de clerc de niveau 5 ou moins sans dépenser d'emplacement de sort (Intervention divine)." },
    { name: "Lame du guerrier-mage", rarity: "Épique", category: "Hybride", effect: "Quand le porteur lance un sort avec une action, il peut effectuer une attaque d'arme avec une action Bonus." },
    { name: "Aura du Super Saiyan", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, le porteur peut utiliser une action Bonus : pendant 1 minute, +2 CA, +20 ft de vitesse, +2 aux jets d'attaque et +1 × son bonus de maîtrise aux dégâts. À la fin, il subit 1 niveau d'Épuisement. (Dragon Ball)" },
    { name: "Kaioken", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, le porteur a une attaque supplémentaire et inflige des dégâts doublés (dés), mais subit 1d10 dégâts non réductibles au début de chacun de ses tours. (Dragon Ball)" },
    { name: "Sparda", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, le porteur peut utiliser une action Bonus pour entrer en forme démoniaque pendant 1 minute : +10 ft de vitesse, +5 ft de portée, résistance au feu, au froid et à la foudre, et il récupère un nombre de PV égal à son bonus de maîtrise au début de chacun de ses tours (Devil Trigger). (Devil May Cry)" },
    { name: "Susanoo", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, une armure spectrale enveloppe le porteur : PV temporaires égaux à 5 × son niveau, +3 CA, +10 ft de portée, et ses attaques d'arme infligent 2d8 dégâts de force supplémentaires. (Naruto)" },
    { name: "Parchemin du mont Myōboku", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, le porteur peut entrer en mode ermite pendant la durée d'un combat : il ajoute son bonus de maîtrise à ses jets d'attaque, de caractéristique et de sauvegarde, et gagne +2 CA. (Naruto)" },
    { name: "Gear Second", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, la vitesse du porteur est doublée, il peut se précipiter par une action Bonus et dispose d'une attaque supplémentaire. (One Piece)" },
    { name: "Temps de l'empereur", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, le porteur ajoute +4 aux jets d'attaque, de caractéristique et de sauvegarde ; à la fin, il subit 1 niveau d'Épuisement. (Hunter x Hunter)" },
    { name: "Bankai", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, +2 aux jets d'attaque, +20 ft de vitesse, une attaque supplémentaire, et l'arme inflige 2d8 dégâts supplémentaires d'un type choisi. (Bleach)" },
    { name: "Flux de Haki des rois", rarity: "Épique", category: "Offensif", effect: "Une fois par combat, les créatures hostiles non-boss à 60 ft du porteur dont les PV maximum sont inférieurs à 10 × son niveau perdent connaissance pendant 1 minute, ou jusqu'à ce qu'elles subissent des dégâts. (One Piece)" },
    { name: "Domaine incomplet", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, le porteur crée une zone de 20 ft de rayon pendant 1 minute : les créatures hostiles à l'intérieur ont le désavantage à leurs jets d'attaque et le porteur l'avantage aux siens. (Jujutsu Kaisen)" },
    { name: "Rinnegan partiel", rarity: "Épique", category: "Offensif", effect: "Une fois par combat, le porteur peut utiliser sa réaction ou une action pour repousser les créatures hostiles à 20 ft (Force, sinon 4d8 dégâts de force et repoussées de 40 ft) ou en attirer une à 5 ft de lui. (Naruto)" },
    { name: "Marteau-tonnerre", rarity: "Épique", category: "Hybride", effect: "Les attaques d'arme du porteur infligent 2d6 dégâts de foudre supplémentaires. Lancé, l'arme a une portée de 60 ft et revient en main. Une fois par étage, il appelle la foudre : 8d8 dégâts de foudre à une créature visible à 120 ft. (Marvel)" },
    { name: "Flamme de l'Ouest", rarity: "Épique", category: "Hybride", effect: "Les attaques d'arme du porteur infligent 2d6 dégâts de feu supplémentaires, et il est immunisé contre l'état Effrayé. Une fois par étage, les créatures hostiles à 30 ft doivent réussir un jet de sauvegarde de Sagesse ou être Effrayées pendant 1 minute. (Le Seigneur des Anneaux)" },
    { name: "Casque de l'ombre", rarity: "Épique", category: "Défensif", effect: "Une fois par combat, le porteur peut utiliser une action Bonus pour devenir insaisissable jusqu'à la fin de son prochain tour : il ne peut être ciblé, ne subit aucun dégât et ne peut pas attaquer. (Percy Jackson)" },
    { name: "Bouclier de vibranium", rarity: "Épique", category: "Hybride", effect: "+2 CA. Une fois par tour, attaque à distance à 60 ft avec le bouclier (ricochet sur jusqu'à 3 créatures) ; il revient en main. Une fois par round, réaction : réduire de 2d10 les dégâts d'une attaque à distance. (Marvel)" },
    { name: "Grande Rune de Godrick", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, +2 à tous les jets d'attaque, de dégâts, de sauvegarde, de caractéristique et à la CA. (Elden Ring)" },
    { name: "Grande Rune de Malenia", rarity: "Épique", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, le porteur récupère un nombre de PV égal à 25 % des dégâts qu'il inflige avec ses attaques d'arme. (Elden Ring)" },
    { name: "Grande Rune de Rykard", rarity: "Épique", category: "Ressources", effect: "Une fois par tour, quand le porteur réduit une créature à 0 PV, il récupère 10 % de ses PV maximum + son bonus de maîtrise en PV. (Elden Ring)" },
    { name: "Grande Rune de Radahn", rarity: "Épique", category: "Offensif", effect: "Une fois par étage, action Bonus : pendant 1 minute, la vitesse des créatures hostiles à 30 ft du porteur est réduite de moitié, sans jet de sauvegarde. (Elden Ring)" },
    { name: "Grande Rune de Mohg", rarity: "Épique", category: "Offensif", effect: "Une fois par étage, le porteur peut sacrifier 25 % de ses PV actuels : jusqu'à la fin du combat, toutes ses attaques infligent 2d6 dégâts nécrotiques supplémentaires. (Elden Ring)" },
    { name: "Grande Rune de Morgott", rarity: "Épique", category: "Défensif", effect: "+3 × niveau PV maximum et résistance aux dégâts de poison et nécrotiques. (Elden Ring)" },
    { name: "Stand : Étoile d'argent", rarity: "Épique", category: "Offensif", effect: "Une fois par combat, par une action, le porteur effectue 5 frappes à mains nues contre une même créature à 10 ft (1d10 + modificateur de Force chacune, dégâts de force). (JoJo's Bizarre Adventure)" },
    { name: "Fruit de la glace", rarity: "Épique", category: "Magique", effect: "Consommable. En mangeant ce fruit, le porteur résiste au froid. Une fois par combat, par une action, il libère un cône de 30 ft : 6d8 dégâts de froid (Constitution pour moitié). L'effet est permanent. Drawback : le porteur ne sait pas nager. (One Piece)" },
    { name: "Fruit de la lumière", rarity: "Épique", category: "Hybride", effect: "Consommable. En mangeant ce fruit, une fois par étage, le porteur peut se déplacer instantanément jusqu'à 60 ft sans provoquer d'attaque d'opportunité et inflige 4d8 dégâts radiants aux créatures sur la trajectoire. L'effet est permanent. Drawback : le porteur ne sait pas nager. (One Piece)" },
    { name: "Fruit de la foudre", rarity: "Épique", category: "Magique", effect: "Consommable. En mangeant ce fruit, le porteur résiste à la foudre. Une fois par combat, par une action, il libère une ligne de 60 ft : 6d10 dégâts de foudre (Dextérité pour moitié). L'effet est permanent. Drawback : le porteur ne sait pas nager. (One Piece)" },
    { name: "Fruit du sable", rarity: "Épique", category: "Magique", effect: "Consommable. En mangeant ce fruit, une fois par combat, par une action, une tempête de sable de 20 ft de rayon à 60 ft aveugle les créatures qui échouent à un jet de Constitution pendant 1 minute. L'effet est permanent. Drawback : le porteur ne sait pas nager, et les attaques à base d'eau le blessent normalement (pas de résistance possible contre elles). (One Piece)" },
    { name: "Contrat Nen", rarity: "Épique", category: "Transformation", effect: "Au début de chaque étage, le porteur prête serment de s'interdire un élément (ses réactions, ses actions Bonus ou la moitié de sa vitesse) : il gagne +2 aux jets d'attaque et 2 × son bonus de maîtrise aux dégâts jusqu'à la fin de l'étage. (Hunter x Hunter)" },
    { name: "Chaîne de jugement", rarity: "Épique", category: "Magique", effect: "Une fois par combat, le porteur désigne une créature : tant qu'il se concentre (1 minute maximum), elle ne peut plus utiliser ses capacités spéciales, seulement attaquer et se déplacer. (Hunter x Hunter)" },
    { name: "Kamehameha", rarity: "Épique", category: "Offensif", effect: "Une fois par étage, le porteur se concentre pendant une action puis libère une ligne de 120 ft : 12d10 dégâts de force (Dextérité pour moitié). (Dragon Ball)" },
    { name: "Haricot de Senzu", rarity: "Épique", category: "Ressources", effect: "Une fois par étage, action Bonus : le porteur récupère tous ses PV, perd tous ses états préjudiciables et récupère tous ses Dés de vie dépensés. (Dragon Ball)" },
    { name: "Soufre", rarity: "Épique", category: "Offensif", effect: "Une fois par combat, par une action, le porteur libère une ligne de 60 ft : 8d6 dégâts de feu (Dextérité pour moitié). (The Binding of Isaac)" },
    { name: "Prescience d'épice", rarity: "Épique", category: "Utilitaire", effect: "Le porteur ne peut pas être surpris. Au premier round de chaque combat, il a l'avantage à toutes ses attaques et sauvegardes. (Dune)" },
    { name: "Couronne du chasseur de rois", rarity: "Épique", category: "Offensif", effect: "+2d8 dégâts à chaque attaque contre un boss. Quand le boss a moins de la moitié de ses PV, ce bonus est doublé." },
    { name: "Médaillon du survivant", rarity: "Épique", category: "Défensif", effect: "Une fois par étage, quand le porteur tombe à 0 PV, il se relève avec la moitié de ses PV maximum et est immunisé contre les dégâts jusqu'à la fin de son prochain tour." },
    { name: "Anneau de l'archimage", rarity: "Épique", category: "Magique", effect: "Les dés de dégâts des sorts de niveau 3 ou plus lancés par le porteur ne peuvent pas donner un résultat inférieur à 3." },
    { name: "Carquois du tireur parfait", rarity: "Épique", category: "Offensif", effect: "+2 aux jets d'attaque à distance, qui ignorent le couvert partiel et à trois-quarts. Une fois par combat, une attaque à distance touche automatiquement." },
    { name: "Étendard de guerre", rarity: "Épique", category: "Hybride", effect: "Exception : au premier round de chaque combat, les alliés à 30 ft du porteur gagnent +1 leur bonus de maîtrise aux dégâts. Le porteur gagne +2 CA tant que l'étendard est déployé (tout le combat)." },
    { name: "Armure du juggernaut", rarity: "Épique", category: "Défensif", effect: "Les dégâts subis par le porteur sont réduits de 2 × son bonus de maîtrise (chaque attaque, sort ou effet, minimum 1 dégât)." },
    { name: "Livre des morts", rarity: "Épique", category: "Magique", effect: "Une fois par combat, le porteur relève comme mort-vivant allié (1 minute) une créature non-boss tuée pendant ce combat ; elle utilise ses statistiques d'origine." },
    { name: "Lame de l'assassin sacré", rarity: "Épique", category: "Offensif", effect: "Au premier round de chaque combat, le porteur a l'avantage aux attaques contre les créatures qui n'ont pas encore joué, et ses touches contre elles sont des coups critiques." },
    { name: "Déluge de la tempête", rarity: "Épique", category: "Offensif", effect: "Une fois par combat, action Bonus : le porteur effectue trois frappes à mains nues contre une ou plusieurs créatures à 5 ft." },
    { name: "Morsure du vampire", rarity: "Épique", category: "Hybride", effect: "Les attaques d'arme du porteur infligent 2d6 dégâts nécrotiques supplémentaires, et il récupère la moitié de ces dégâts en PV." },
    { name: "Anneau des trois souhaits", rarity: "Épique", category: "Transformation", effect: "Contient 3 charges. Le porteur peut dépenser une charge pour lancer Souhait (Wish). Quand les 3 charges sont épuisées, l'anneau devient une bague ordinaire. (Objet DnD)" },
    { name: "Armure de plates +3", rarity: "Épique", category: "Défensif", effect: "Armure lourde magique. CA 21. (Objet DnD)" },
    { name: "Veste de Spiderman", rarity: "Épique", category: "Utilitaire", effect: "Le porteur gagne une vitesse d'escalade égale à sa vitesse de marche, peut marcher sur les plafonds, et ne peut pas être Entravé par des toiles ou des effets similaires. Une fois par combat, par une action Bonus, il projette une toile sur une créature à 30 ft : elle est Entravée (Force DD 8 + bonus de maîtrise du porteur pour se libérer, action). (Marvel)" },
    { name: "Doigt de Sukuna", rarity: "Épique", category: "Transformation", effect: "Consommable. En le mangeant (action), le porteur absorbe une fraction de la puissance de Ryomen Sukuna : ses attaques d'arme infligent 1d10 dégâts de force supplémentaires et il regagne 2 × son bonus de maîtrise PV au début de chacun de ses tours. L'effet est permanent. Drawback : au début de chaque étage, le porteur doit réussir un jet de sauvegarde de Sagesse DD 16 ou être sous le contrôle du MJ pendant son premier tour (Sukuna prend le dessus). (Jujutsu Kaisen)" },
    { name: "Orbe de Neron", rarity: "Épique", category: "Ressources", effect: "Le porteur gagne 3 emplacements de sort supplémentaires de niveau 5 ou moins (au choix), reconstituables à chaque étage. Drawback : chaque fois qu'il dépense un de ces emplacements supplémentaires, il subit 1d6 dégâts nécrotiques non réductibles (pacte avec un démon)." },

    // --- LÉGENDAIRES ---
    { name: "Œil d'Agamotto", rarity: "Légendaire", category: "Transformation", effect: "Une fois par étage, le porteur annule tout ce qui s'est produit depuis le début de son dernier tour : PV, états, ressources, positions et utilisations sont restaurés pour toutes les créatures, et il rejoue son tour en conservant la mémoire de ce qui s'est passé. (Doctor Strange)" },
    { name: "Joyau de l'Espace", rarity: "Légendaire", category: "Utilitaire", effect: "À volonté, une fois par tour et sans action, le porteur se téléporte jusqu'à 60 ft dans un espace visible. Une fois par étage, il échange la position de deux créatures visibles à 120 ft. (Marvel)" },
    { name: "Joyau de Réalité", rarity: "Légendaire", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, les dégâts du porteur ignorent résistances et immunités (il choisit si une vulnérabilité s'applique) et il peut changer le type de dégâts de chaque attaque ou sort. (Marvel)" },
    { name: "Joyau de Puissance", rarity: "Légendaire", category: "Offensif", effect: "Une fois par combat, pendant un tour, tous les dés de dégâts des attaques et sorts du porteur sont maximisés. (Marvel)" },
    { name: "Joyau de l'Âme", rarity: "Légendaire", category: "Ressources", effect: "Chaque fois qu'une créature hostile meurt à 60 ft du porteur, il récupère des PV égaux à son niveau + son bonus de maîtrise et gagne +1 aux jets d'attaque et de dégâts jusqu'à la fin du combat (cumulable jusqu'à +5). (Marvel)" },
    { name: "Sceptre de l'Esprit", rarity: "Légendaire", category: "Transformation", effect: "Au début de chaque round, le porteur choisit une créature hostile visible : elle est Charmée par lui jusqu'à la fin du round, sans jet de sauvegarde (un boss fait un jet de Sagesse avec avantage). (Marvel)" },
    { name: "Baguette de sureau", rarity: "Légendaire", category: "Magique", effect: "Quand le porteur touche avec un sort d'attaque ou qu'une créature échoue à une sauvegarde contre l'un de ses sorts, les dégâts sont maximisés. Ses sorts ne peuvent être ni contrés ni dissipés. (Harry Potter)" },
    { name: "Pierre de Résurrection", rarity: "Légendaire", category: "Ressources", effect: "Une fois par étage, par une action, le porteur ramène à la vie un aventurier mort, avec tous ses PV et toutes ses ressources. (Harry Potter)" },
    { name: "Cape de la Mort", rarity: "Légendaire", category: "Utilitaire", effect: "Le porteur est Invisible en permanence aux yeux des créatures non-boss ; attaquer ou lancer un sort ne rompt pas cette invisibilité. Les boss le perçoivent normalement. (Harry Potter)" },
    { name: "Retourneur de temps", rarity: "Légendaire", category: "Transformation", effect: "Une fois par combat, le porteur joue un tour supplémentaire complet (action, action Bonus, déplacement) immédiatement après son tour normal. (Harry Potter)" },
    { name: "Pierre philosophale", rarity: "Légendaire", category: "Ressources", effect: "Les PV que le porteur récupère sont doublés. Une fois par étage, par une action Bonus, il récupère tous ses PV et tous ses Dés de vie dépensés. (Harry Potter)" },
    { name: "Anneau unique", rarity: "Légendaire", category: "Hybride", effect: "Le porteur peut devenir Invisible à volonté (action Bonus). Une fois par étage, une créature non-boss à 30 ft est asservie pendant 1 minute, sans jet de sauvegarde. En contrepartie, le porteur a le désavantage à ses jets de sauvegarde de Sagesse. (Le Seigneur des Anneaux)" },
    { name: "Holocron ancien", rarity: "Légendaire", category: "Magique", effect: "Une fois par combat, le porteur peut étrangler à distance : une créature non-boss de taille Grande ou inférieure est soulevée et Neutralisée tant qu'il se concentre (1 minute maximum). Un boss n'est affecté que pendant un round. (Star Wars)" },
    { name: "Ocarina du temps", rarity: "Légendaire", category: "Transformation", effect: "Une fois par étage, à tout moment d'un combat, le porteur joue le Chant du temps : l'équipe et les créatures reviennent au début de ce combat, avec leurs PV, ressources et positions d'alors. Le porteur conserve la mémoire de ce qui s'est passé. (The Legend of Zelda)" },
    { name: "Triforce de Puissance", rarity: "Légendaire", category: "Offensif", effect: "+5 aux jets de dégâts. Les attaques du porteur infligent un coup critique sur un 18, 19 ou 20 naturel et leurs dégâts ignorent les résistances. (The Legend of Zelda)" },
    { name: "Triforce de Sagesse", rarity: "Légendaire", category: "Magique", effect: "+3 au DD et aux jets d'attaque de sort. Les créatures ont le désavantage à leurs jets de sauvegarde contre les sorts du porteur, qui ignorent les résistances aux dégâts. (The Legend of Zelda)" },
    { name: "Triforce de Courage", rarity: "Légendaire", category: "Défensif", effect: "Le porteur est immunisé contre les états Effrayé, Charmé, Étourdi et Paralysé. Une fois par round, il peut transformer un échec à un jet de sauvegarde en réussite, sans dépenser d'action. (The Legend of Zelda)" },
    { name: "Foudre maîtresse", rarity: "Légendaire", category: "Offensif", effect: "Une fois par étage, par une action, chaque créature hostile visible à 120 ft subit 20d10 dégâts de foudre (Dextérité pour moitié ; un boss subit seulement 10d10). (Percy Jackson)" },
    { name: "Trident des mers", rarity: "Légendaire", category: "Offensif", effect: "Une fois par étage, par une action, un raz-de-marée frappe les créatures hostiles à 60 ft : 6d10 dégâts contondants et état À terre (Force pour moitié et sans l'état ; un boss a l'avantage au jet). (Percy Jackson)" },
    { name: "Bident d'Hadès", rarity: "Légendaire", category: "Hybride", effect: "Une fois par tour, le porteur peut exécuter une créature non-boss qui a moins du quart de ses PV, sans jet : elle meurt et aucun effet ne peut la relever. (Percy Jackson)" },
    { name: "Dragon Balls", rarity: "Légendaire", category: "Ressources", effect: "Une fois par run, le porteur peut rassembler les sept boules : tous les aventuriers morts reviennent à la vie avec tous leurs PV, et chaque aventurier récupère toutes ses ressources (hors artefacts). (Dragon Ball)" },
    { name: "Instinct ultime", rarity: "Légendaire", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, la première attaque de chaque créature par round contre le porteur échoue automatiquement, ses propres attaques ont l'avantage, et il ne peut pas être surpris. (Dragon Ball)" },
    { name: "Technique de téléportation", rarity: "Légendaire", category: "Utilitaire", effect: "Une fois par tour, sans action, le porteur se téléporte à côté de n'importe quelle créature visible. Une fois par combat, il peut emmener deux alliés. (Dragon Ball)" },
    { name: "Flèche Requiem", rarity: "Légendaire", category: "Transformation", effect: "Au début de chaque étage, le porteur choisit l'une de ses capacités (sort, capacité de classe, attaque d'arme ou artefact) : ses dés de dégâts ou de soin sont doublés, ses utilisations limitées sont doublées, et elle ignore les immunités aux dégâts. (JoJo's Bizarre Adventure)" },
    { name: "Stand : Le Monde", rarity: "Légendaire", category: "Transformation", effect: "Une fois par étage, au début de son tour, le porteur arrête le temps : il joue 3 tours consécutifs pendant lesquels les autres créatures sont Neutralisées (un boss ne l'est que pendant le premier). (JoJo's Bizarre Adventure)" },
    { name: "Stand : Cramoisi", rarity: "Légendaire", category: "Transformation", effect: "Une fois par combat, au début d'un round, le porteur efface le temps : tout ce que font les créatures hostiles pendant ce round (attaques, sorts, effets) n'a aucun effet, et il agit normalement. (JoJo's Bizarre Adventure)" },
    { name: "Stand : Expérience dorée Requiem", rarity: "Légendaire", category: "Défensif", effect: "Une fois par combat, quand une créature inflige des dégâts ou un état au porteur ou à un allié, l'effet est annulé comme s'il ne s'était jamais produit, et la créature perd le reste de son tour. (JoJo's Bizarre Adventure)" },
    { name: "Six Chemins", rarity: "Légendaire", category: "Offensif", effect: "Une fois par round, action Bonus : le porteur repousse de 40 ft ou attire à 5 ft toutes les créatures hostiles à 60 ft (Force, sinon 6d8 dégâts de force). Une fois par combat, il peut annuler un sort lancé par une créature (réaction). (Naruto)" },
    { name: "Izanagi", rarity: "Légendaire", category: "Défensif", effect: "Une fois par run, quand le porteur est réduit à 0 PV ou meurt, l'événement est annulé : il récupère tous ses PV, perd tous ses états et rejoue son dernier round. L'artefact est consommé. (Naruto)" },
    { name: "Kamui", rarity: "Légendaire", category: "Défensif", effect: "Une fois par combat, quand une créature cible le porteur, il peut utiliser sa réaction pour devenir intangible jusqu'au début de son prochain tour : aucun dégât ni effet, il traverse créatures et objets et peut se téléporter à 30 ft. (Naruto)" },
    { name: "Chakra du démon-renard", rarity: "Légendaire", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, +2 CA et aux jets d'attaque, deux attaques supplémentaires, +20 ft de vitesse, +1 × son bonus de maîtrise aux dégâts et 10 × son niveau en PV temporaires. (Naruto)" },
    { name: "Extension du domaine : Vide infini", rarity: "Légendaire", category: "Transformation", effect: "Une fois par étage, le porteur crée une zone de 30 ft de rayon pendant 1 minute : les créatures hostiles à l'intérieur sont Neutralisées (un boss peut faire un jet de Sagesse à chacun de ses tours pour y échapper). (Jujutsu Kaisen)" },
    { name: "Extension du domaine : Sanctuaire malveillant", rarity: "Légendaire", category: "Offensif", effect: "Une fois par étage, le porteur crée une zone de 30 ft de rayon pendant 1 minute : au début de chaque round, chaque créature hostile dedans subit 5d10 dégâts tranchants, sans jet (un boss subit la moitié). (Jujutsu Kaisen)" },
    { name: "Six Yeux", rarity: "Légendaire", category: "Défensif", effect: "Tant que le porteur n'a pas attaqué pendant son dernier tour, les créatures hostiles ne peuvent ni le cibler par une attaque de mêlée ni s'approcher à moins de 10 ft de lui. (Jujutsu Kaisen)" },
    { name: "Bankai absolu", rarity: "Légendaire", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, +4 aux jets d'attaque, dés de dégâts de l'arme doublés, deux attaques supplémentaires et +30 ft de vitesse. À la fin, le porteur subit 2 niveaux d'Épuisement. (Bleach)" },
    { name: "Gear Fifth", rarity: "Légendaire", category: "Transformation", effect: "Une fois par étage, action Bonus : pendant 1 minute, les dégâts du porteur ignorent résistances et immunités, il est immunisé contre Entravé et À terre, sa portée de mêlée augmente de 15 ft et, une fois par round, il peut annuler les dégâts d'une attaque (réaction). (One Piece)" },
    { name: "Fruit de l'opération", rarity: "Légendaire", category: "Transformation", effect: "Consommable. En mangeant ce fruit, une fois par étage, le porteur déploie une Salle de 60 ft de rayon pendant 1 minute : à chacun de ses tours, il échange la position de deux créatures ou objets dans la Salle et peut priver une créature de son action pour ce tour, sans jet. L'effet est permanent. Drawback : le porteur ne sait pas nager. (One Piece)" },
    { name: "Orbe du Grand Sage", rarity: "Légendaire", category: "Utilitaire", effect: "Orbe de cristal noir. Au début de chaque combat, le porteur connaît la CA, les PV, les résistances, immunités, vulnérabilités et capacités de chaque créature hostile. Ses jets de d20 ne peuvent pas donner un résultat inférieur à 10. (Tensura)" },
    { name: "Collier du Prédateur", rarity: "Légendaire", category: "Ressources", effect: "Collier fait de crânes miniatures. Quand le porteur réduit une créature non-boss à 0 PV, il peut absorber l'une de ses attaques ou capacités via le collier et l'utiliser une fois par étage (3 capacités stockées au maximum ; la plus ancienne est perdue). (Tensura)" },
    { name: "Arme ultime", rarity: "Légendaire", category: "Offensif", effect: "Chaque attaque d'arme du porteur inflige 2d10 dégâts supplémentaires pour chaque quart de ses PV maximum manquant (jusqu'à +8d10). (Final Fantasy)" },
    { name: "Omnislash", rarity: "Légendaire", category: "Offensif", effect: "Une fois par étage, par une action, le porteur effectue jusqu'à 15 attaques d'arme réparties à volonté entre les créatures visibles à 60 ft, avec un déplacement instantané entre cibles sans attaque d'opportunité. (Final Fantasy)" },
    { name: "Âme de seigneur", rarity: "Légendaire", category: "Transformation", effect: "Après avoir vaincu un boss, le porteur peut consommer son âme (action) : il récupère tous ses PV et toutes ses ressources, et gagne +2 aux jets d'attaque, de dégâts, de sauvegarde et à la CA pendant tout l'étage suivant. (Dark Souls)" },
    { name: "Première Flamme", rarity: "Légendaire", category: "Ressources", effect: "Une fois par run, quand tous les aventuriers sont à 0 PV, le porteur rallume la flamme : l'équipe recommence l'étage en cours avec tous ses PV et toutes ses ressources, en conservant ses passifs et artefacts. (Dark Souls)" },
    { name: "Cercle d'Elden", rarity: "Légendaire", category: "Transformation", effect: "Une fois par étage, le porteur proclame un Ordre pendant 1 minute : les créatures hostiles ne peuvent pas utiliser de réactions, ou ne peuvent pas lancer de sorts, ou ne peuvent pas se déplacer, ou ne peuvent pas récupérer de PV (au choix du porteur). (Elden Ring)" },
    { name: "Gobelet de café", rarity: "Légendaire", category: "Hybride", effect: "Le porteur gagne une action supplémentaire à chaque round (hors action Magie). En contrepartie, il ne récupère plus ni PV ni ressources grâce aux sanctuaires et aux repos. (Slay the Spire)" },
    { name: "Sacred Heart", rarity: "Légendaire", category: "Offensif", effect: "+2d6 aux dégâts de chaque attaque et sort du porteur, qui ignorent le couvert et ne subissent aucun désavantage. +5 PV maximum. (The Binding of Isaac)" },
    { name: "Verre éphémère", rarity: "Légendaire", category: "Offensif", effect: "Tous les dés de dégâts du porteur sont doublés. Ses PV maximum sont réduits de moitié (arrondi supérieur). (Risk of Rain)" },
    { name: "Miroir de la nuit", rarity: "Légendaire", category: "Défensif", effect: "Trois fois par run, quand le porteur tombe à 0 PV, il se relève avec la moitié de ses PV maximum et chaque créature hostile à 30 ft est repoussée de 20 ft. (Hades)" },
    { name: "Prescience du Kwisatz Haderach", rarity: "Légendaire", category: "Utilitaire", effect: "Au début de chaque round, le porteur lance deux d20 et conserve leurs résultats : il peut remplacer n'importe quel jet de d20 (le sien ou celui d'une créature visible) par l'un d'eux. (Dune)" },
    { name: "Pilule rouge", rarity: "Légendaire", category: "Utilitaire", effect: "Une fois par round, après le jet de d20 d'une créature située à 60 ft, le porteur peut remplacer le résultat par 10. (Matrix)" },
    { name: "Katana de l'immortel", rarity: "Légendaire", category: "Ressources", effect: "Quand le porteur réduit une créature d'un combat difficile ou un boss à 0 PV, il récupère 3 × son niveau en PV et gagne +1 aux jets d'attaque et de dégâts jusqu'à la fin de la run (maximum +5). (Highlander)" },
    { name: "Thu'um", rarity: "Légendaire", category: "Offensif", effect: "Une fois par combat, action Bonus : cône de 60 ft, les créatures hostiles doivent réussir un jet de Force ou subir 10d6 dégâts de force, être repoussées de 40 ft et Neutralisées jusqu'au début de leur prochain tour. (Skyrim)" },
    { name: "Excalibur", rarity: "Légendaire", category: "Hybride", effect: "Les attaques d'arme du porteur infligent 3d8 dégâts radiants supplémentaires et ignorent les immunités. Une fois par étage, une ligne de lumière de 100 ft inflige 10d10 dégâts radiants (Dextérité pour moitié). (Légende arthurienne)" },
    { name: "Gungnir", rarity: "Légendaire", category: "Offensif", effect: "Les attaques d'arme du porteur avec cette lance touchent automatiquement une créature visible à 120 ft ; la lance revient en main. Une fois par étage, une attaque de ce type est un coup critique. (Mythologie nordique)" },
    { name: "Sablier de Chronos", rarity: "Légendaire", category: "Transformation", effect: "Au début de chaque round, le porteur se place à n'importe quelle position de l'ordre d'initiative pour ce round. Une fois par combat, il peut interrompre le tour d'une créature pour jouer immédiatement le sien." },
    { name: "Cœur d'Infernity", rarity: "Légendaire", category: "Transformation", effect: "Chaque boss vaincu augmente de manière permanente (jusqu'à la fin de la run) les jets d'attaque et la CA du porteur de +1 (maximum +5)." },
    { name: "Couronne du régicide", rarity: "Légendaire", category: "Offensif", effect: "Les boss ne peuvent pas dépenser de Résistance légendaire contre les sorts et capacités du porteur. Ses attaques contre un boss ignorent résistances et immunités et infligent 2 × son niveau en dégâts supplémentaires." },
    { name: "Clé du cartographe infernal", rarity: "Légendaire", category: "Utilitaire", effect: "Une fois par étage, le porteur peut remplacer la prochaine salle de combat qui n'est pas un boss par un sanctuaire." },
    { name: "Tablettes de la destinée", rarity: "Légendaire", category: "Utilitaire", effect: "Deux tablettes de pierre gravées. Au début de chaque étage, le porteur lit les tablettes : il connaît l'intégralité du prochain combat (composition ennemie, PV, capacités spéciales, ordre d'initiative). Une fois par étage, il peut réécrire le destin : une créature hostile de son choix commence le combat avec seulement la moitié de ses PV. (Mythologie sumérienne)" },
    { name: "Potion de divinité", rarity: "Légendaire", category: "Ressources", effect: "Consommable unique par run. Action : le porteur boit la potion et devient temporairement divin pendant 3 rounds : il est immunisé contre tous les dégâts et états, ses attaques touchent automatiquement et sont des coups critiques, et ses sorts maximisent leurs dés. Après l'effet, il subit 3 niveaux d'Épuisement. (Inspiration mythologique)" },
    { name: "Manuscrit de l'Alchimiste", rarity: "Légendaire", category: "Transformation", effect: "Grimoire relié en cuir. Au début de chaque étage, le porteur peut transmetuer l'un de ses artefacts équipés (hors Légendaire) : il choisit un nouvel artefact de même rareté au hasard parmi 3 options. L'ancien artefact est perdu. Une fois par run, il peut transmetuer un artefact Rare en Épique. (Full Metal Alchemist)" },
    { name: "Bague de Sauron", rarity: "Légendaire", category: "Hybride", effect: "Le porteur est invisible à volonté (action Bonus, se rompt à l'attaque ou au sort). Une fois par combat, toutes les créatures hostiles non-boss à 60 ft doivent réussir un jet de Sagesse DD 20 ou être Charmées pendant 1 minute. Les boss ont l'avantage. Drawback : le porteur a le désavantage permanent à ses jets de sauvegarde de Sagesse et subit 1 niveau d'Épuisement à la fin de chaque étage où il a utilisé la bague. (Le Seigneur des Anneaux)" }
